export function createValidPngBuffer(): Buffer {
  // PNG signature: 89 50 4E 47 0D 0A 1A 0A followed by IHDR chunk
  return Buffer.from([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
    0x00, 0x00, 0x00, 0x0d, 0x49, 0x48, 0x44, 0x52,
    0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01,
    0x08, 0x06, 0x00, 0x00, 0x00, 0x1f, 0x15, 0xc4,
    0x89, 0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82
  ]);
}

export function createValidJpegBuffer(): Buffer {
  // JPEG signature: FF D8 FF E0 followed by JFIF header
  return Buffer.from([
    0xff, 0xd8, 0xff, 0xe0, 0x00, 0x10, 0x4a, 0x46,
    0x49, 0x46, 0x00, 0x01, 0x01, 0x01, 0x00, 0x48,
    0x00, 0x48, 0x00, 0x00, 0xff, 0xdb, 0x00, 0x43,
    0xff, 0xd9
  ]);
}

export function createValidPdfBuffer(): Buffer {
  // PDF signature: %PDF-1.4 ... %%EOF
  return Buffer.from('%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\ntrailer\n<< /Root 1 0 R >>\n%%EOF');
}

export function createDisallowedExeBuffer(): Buffer {
  // MZ DOS/PE Executable signature: 4D 5A
  return Buffer.from([0x4d, 0x5a, 0x90, 0x00, 0x03, 0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00]);
}

export function createDisallowedScriptBuffer(): Buffer {
  return Buffer.from('#!/bin/bash\necho "exploit execution attempted"\n');
}

export function createOversizedBuffer(): Buffer {
  // 10.5 MB buffer (exceeds 10 MB limit)
  return Buffer.alloc(10.5 * 1024 * 1024, 0xaa);
}
